package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.*;import com.hmdp.ai.runtime.tool.skill.dto.*;import com.hmdp.dto.ai.ReviewDoc;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;
@Component @AgentSkill(code="ask-about-shop") public class AskAboutShopSkill extends ShopSkillSupport implements LocalSkill {public AskAboutShopSkill(ShopDataPort s,ReviewDataPort r,ObjectMapper m){super(s,r,m);}@Override public JsonNode execute(ExecutionContext c,JsonNode in){long id=shopId(in);String q=in.path("question").asText("").trim();if(q.isEmpty())throw new IllegalArgumentException("question is required");Set<String>terms=Arrays.stream(q.toLowerCase().split("[^\\p{L}\\p{N}]+" )).filter(x->x.length()>=2).collect(Collectors.toSet());List<ReviewDoc>matches=reviews.findReviewsByShopId(id).stream().filter(d->matches(d,terms)).limit(10).collect(Collectors.toList());return json(new ShopQuestionEvidenceData(id,q,shops.getShop(id),evidence(matches),matches.isEmpty()));}private boolean matches(ReviewDoc d,Set<String>t){String text=((d.getTitle()==null?"":d.getTitle())+" "+(d.getContent()==null?"":d.getContent())).toLowerCase();return t.isEmpty()||t.stream().anyMatch(text::contains);}}
